@RunWith(JUnit4.class)
public class WriteableCommandLineImpl_getValues_TriageGen2Test {

    @Test
    public void testGetValues_NoDefaultValues() throws OptionException {
        // given
        Option option = new Option("option");
        List defaultValues = null;
        WriteableCommandLineImpl writeableCommandLine = new WriteableCommandLineImpl(option, defaultValues);

        // when
        List values = new ArrayList();
        values.add(option);
        writeableCommandLine.values.put(option, values);
        List result = writeableCommandLine.getValues(option, null);

        // then
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testGetValues_WithDefaultValues_NoOptionInValues() throws OptionException {
        // given
        Option option = new Option("option");
        List defaultValues = new ArrayList();
        defaultValues.add("default-value");
        WriteableCommandLineImpl writeableCommandLine = new WriteableCommandLineImpl(option, defaultValues);

        // when
        List result = writeableCommandLine.getValues(option, defaultValues);

        // then
        assertNotNull(result);
        assertEquals(1, result.size());
        assertEquals("default-value", result.get(0));
    }

    @Test
    public void testGetValues_WithDefaultValues_HasOptionInValues() throws OptionException {
        // given
        Option option = new Option("option");
        List defaultValues = new ArrayList();
        defaultValues.add("default-value");
        List values = new ArrayList();
        values.add(option);
        WriteableCommandLineImpl writeableCommandLine = new WriteableCommandLineImpl(option, defaultValues);
        writeableCommandLine.values.put(option, values);

        // when
        List result = writeableCommandLine.getValues(option, defaultValues);

        // then
        assertNotNull(result);
        assertEquals(1, result.size());
        assertEquals("default-value", result.get(0));
    }

    @Test
    public void testGetValues_WithDefaultValuesAndSwitch_HasOptionInValues() throws OptionException {
        // given
        Option option = new Option("option");
        List defaultValues = new ArrayList();
        defaultValues.add("default-value");
        List switchValues = new ArrayList();
        switchValues.add(true);
        List values = new ArrayList();
        values.add(option);
        WriteableCommandLineImpl writeableCommandLine = new WriteableCommandLineImpl(option, defaultValues);
        writeableCommandLine.defaultSwitches.put(option, switchValues);
        writeableCommandLine.values.put(option, values);

        // when
        List result = writeableCommandLine.getValues(option, defaultValues);

        // then
        assertNotNull(result);
        assertEquals(2, result.size());
        assertEquals("default-value", result.get(0));
        assertEquals(true, result.get(1));
    }

